  "jxg.paste_first":        "Collez d'abord le code généré par l'IA.",
  "jxg.copied_prompt":      "✅ Prompt copié !",
  "jxg.preview_btn":        "👁 Prévisualiser",
  "jxg.preview_lbl":        "Aperçu (rendu JSXGraph du code collé) :",
  "jxg.preview_first":      "Collez d'abord du code à prévisualiser.",

  "jxg.prompt_intro":       "Tu génères un graphique JSXGraph CLASSIQUE et AUTONOME (testable seul dans un\nnavigateur). Ne te préoccupe PAS de STACK/Moodle : je convertis moi-même ton\ncode ensuite (syntaxe [[jsxgraph]], divid, {#…#}) — inutile de la connaître.",
  "jxg.prompt_rules_header":"━━ RÈGLES ━━",
  "jxg.prompt_rule1":       "1. Structure complète et autonome :\n   <div id=\"box\" style=\"width:{w};height:{h};\"></div>\n   <script src=\"https://cdn.jsdelivr.net/npm/jsxgraph/distrib/jsxgraphcore.js\"></script>\n   <script>\n   var board = JXG.JSXGraph.initBoard('box', {…});\n   … ton code …\n   </script>",
  "jxg.prompt_rule2":       "2. Nomme la variable du board EXACTEMENT \"board\" et le conteneur EXACTEMENT\n   \"box\" (comme dans le squelette ci-dessous).",
  "jxg.prompt_rule3":       "3. Si tu utilises une des variables listées plus bas, déclare-la avec une\n   valeur d'exemple ET le commentaire // POOLVAR: nom sur la MÊME ligne\n   (ex: var a = 3; // POOLVAR: a) — c'est ce qui me permet de la relier\n   automatiquement après conversion.",
  "jxg.prompt_rule4":       "4. Encadre le tracé de board.suspendUpdate() / board.unsuspendUpdate().",
  "jxg.prompt_rule5_interactive": "5. Ce graphique est INTERACTIF : les points que l'élève doit pouvoir déplacer\n   sont des points JSXGraph normaux, déplaçables (PAS fixed:true). Juste après\n   la ligne board.create('point', …) de CHAQUE point interactif, ajoute un\n   commentaire // BIND: nomVariable (ex: // BIND: ans1) indiquant à quelle\n   variable de réponse STACK il correspond — je ferai le branchement\n   stack_jxg.bind_point moi-même après conversion.",
  "jxg.prompt_rule5_display":     "5. Ce graphique est en AFFICHAGE SEUL (non interactif) : tous les objets\n   JSXGraph DOIVENT avoir {fixed:true, highlight:false, visible:true}\n   (les trois — STACK a besoin de visible:true en plus de fixed:true).",
  "jxg.prompt_config_header":"━━ CONFIGURATION DU REPÈRE (à respecter exactement) ━━",
  "jxg.prompt_window":      "Fenêtre : x de {xmin} à {xmax}, y de {ymin} à {ymax}",
  "jxg.prompt_options":     "Options : {opts}",
  "jxg.prompt_vars_header": "━━ VARIABLES DISPONIBLES ━━",
  "jxg.prompt_var_line":    "  {n}  →  var {n} = <valeur d'exemple>; // POOLVAR: {n}",
  "jxg.prompt_no_vars":     "(aucune variable définie dans le pool pour ce questionnaire)",
  "jxg.prompt_skeleton_header": "━━ SQUELETTE DE RÉFÉRENCE (utiliser cette config exacte pour initBoard) ━━",
  "jxg.prompt_request_header":  "━━ DEMANDE ━━",
  "jxg.prompt_no_desc":     "(aucune description fournie)",
  "jxg.prompt_draw_here":   "/* --- tracé ici --- */",
  "jxg.prompt_reticule_comment": "/* --- réticule : lignes croisées + coordonnées au survol --- */",
  "jxg.prompt_footer":      "Réponds UNIQUEMENT avec le code (div + script), prêt à coller et tester dans\nun navigateur, entouré d'un bloc de code markdown (```html au début, ```\nà la fin) — sans quoi certaines interfaces de chat exécutent le HTML/JS\nau lieu de l'afficher comme du texte. Pas d'explication avant ou après.",
