  "match.prompt_ctx_base":       "{matter} de niveau {level}",
  "match.prompt_ctx_sous":       ", sous-matière « {sous} »",
  "match.prompt_ctx_chap":       ", chapitre « {chap} »",
  "match.prompt_role":           "### RÔLE\nTu es un ingénieur pédagogique expert en conception d'évaluations interactives (Matching Questions). Ta mission est de générer un exercice de mise en relation de concepts structuré en JSON.",
  "match.prompt_consigne_title": "### CONSIGNE",
  "match.prompt_consigne":       "Génère un exercice de type « Appariement » sur le sujet suivant : {subject} pour un exercice en {ctx}.",
  "match.prompt_bullet_left":    "La colonne de gauche (leftItems) contient des concepts, des exemples précis, des valeurs ou des cas concrets.",
  "match.prompt_bullet_right":   "La colonne de droite (rightItems) contient des catégories générales, des définitions, des propriétés ou des seuils.",
  "match.prompt_bullet_constraint": "CONTRAINTE PÉDAGOGIQUE OBLIGATOIRE (NON 1-à-1) : L'exercice ne doit PAS être une simple correspondance linéaire. Conçois l'exercice pour qu'un élément de droite soit lié à plusieurs éléments de gauche (relation Plusieurs-à-Un), ou qu'un élément de gauche soit associé à plusieurs propriétés à droite (Plusieurs-à-Plusieurs).",
  "match.prompt_bullet_lang":    "La langue à utiliser est {lang}.",
  "match.prompt_tech_title":     "### CONTRAINTES TECHNIQUES STRICTES",
  "match.prompt_tech1":          "1. FORMAT DE SORTIE : JSON pur uniquement (pas de blabla, pas de balises markdown de code block, juste l'objet JSON).",
  "match.prompt_tech2":          "2. STRUCTURE DES ITEMS : Chaque objet dans « leftItems » et « rightItems » doit obligatoirement avoir cette structure exacte :",
  "match.prompt_tech3":          "3. STRUCTURE DES CONNECTIONS : Le tableau « connections » doit être un tableau de paires d'indices numériques (commençant à 0). Exemple : [[0, 0], [1, 2], [2, 2]]. Ne pas utiliser d'objets avec des clés leftId/rightId.",
  "match.prompt_tech4":          "4. ASYMÉTRIE : Le nombre d'éléments à gauche et à droite doit être différent. Un même index de droite DOIT apparaître plusieurs fois dans le tableau « connections » pour valider la structure non linéaire.",
  "match.prompt_tech5":          "5. ÉCHAPPEMENT JSON : à l'intérieur des chaînes, double tout antislash (\\\\) et échappe les guillemets internes (\\\"). Échappe correctement les guillemets dans les attributs HTML. Le JSON doit être valide tel quel.",
  "match.prompt_example_title":  "### EXEMPLE DE STRUCTURE ATTENDUE (Modèle asymétrique Plusieurs-à-Un)",
  "match.prompt_example_left1":  "Chien",
  "match.prompt_example_left2":  "Aigle",
  "match.prompt_example_left3":  "Chat",
  "match.prompt_example_right1": "Mammifères",
  "match.prompt_example_right2": "Oiseaux",
  "match.prompt_final_title":    "### CONTRÔLE FINAL (avant de répondre)",
  "match.prompt_final_check":    "Vérifie que : (1) le JSON est syntaxiquement valide ; (2) tous les antislashes sont doublés et les guillemets internes échappés ; (3) la structure (id/html/text, connections en paires d'indices) est respectée ; (4) l'asymétrie est présente ; (5) aucun texte hors du bloc JSON. Si tu ne peux pas respecter ces contraintes, renvoie un objet JSON vide {}.",
  "match.prompt_task_title":     "### TÂCHE",
  "match.prompt_task":           "Génère maintenant le JSON final pour le sujet : {subject}",

