  "cw.prompt_ctx_base":   "{matter} en classe de {level}",
  "cw.prompt_ctx_sous":   ", sous-matière « {sous} »",
  "cw.prompt_ctx_chap":   ", chapitre « {chap} »",
  "cw.prompt_role":       "Tu es un créateur de mots croisés expert et un enseignant pédagogue de {ctx} . Génère une liste de mots et leurs définitions pour créer une grille de mots croisés.",
  "cw.prompt_theme_lbl":  "Thème demandé : {theme}",
  "cw.prompt_count_lbl":  "Nombre de mots à générer : {count}",
  "cw.prompt_lang_lbl":   "Langue : {lang}",
  "cw.prompt_rules_lbl":  "Règles strictes d'interconnexion :",
  "cw.prompt_rule2":      "2. VÉRIFICATION CROISÉE : Avant de lister un mot, assure-toi qu'il partage AU MOINS une lettre avec au moins 2 autres mots de ta liste.",
  "cw.prompt_rule3":      "3. Les mots doivent contenir entre 4 et 10 lettres. Évite les mots de 2 ou 3 lettres qui bloquent la grille.",
  "cw.prompt_rule4":      "4. Les définitions doivent être courtes, claires et au style typique des mots croisés.",
  "cw.prompt_rule5":      "5. Écris les mots en MAJUSCULES sans accents pour le champ \"word\" (ex: \"ECOLE\" et non \"École\"). Tu peux mettre des accents dans les définitions.",
  "cw.prompt_rule6":      "6. INTERDICTION ABSOLUE : la définition ne doit JAMAIS contenir le mot à trouver, ni un mot de la même famille (même racine). Par exemple, pour le mot \"RÉACTION\", la définition ne doit contenir ni \"réaction\", ni \"réagir\", ni \"réactif\".",
  "cw.prompt_rule7":      "7. NATURE DES MOTS : chaque mot doit être un NOM COMMUN au SINGULIER. Pas de noms propres, pas de pluriels, pas de verbes conjugués, pas de mots composés (ni espace ni trait d'union).",
  "cw.prompt_json_instr": "Génère UNIQUEMENT un tableau JSON valide, sans aucun texte supplémentaire avant ou après, en utilisant exactement cette structure :",
  "cw.prompt_json_word_ph": "MOT",
  "cw.prompt_json_def_ph":  "Définition du mot ici",
  "cw.prompt_final_check": "CONTRÔLE FINAL (à vérifier avant de répondre) :",
  "cw.prompt_check1":     "- Le tableau JSON est syntaxiquement valide (virgules, guillemets, crochets corrects).",
  "cw.prompt_check2":     "- Tout antislash éventuel est doublé (\\\\) et tout guillemet interne est échappé (\\\") pour rester un JSON valide.",
  "cw.prompt_check3":     "- Aucune définition ne contient son propre mot (règle 6) ; tous les mots sont des noms communs au singulier (règle 7).",
  "cw.prompt_check4":     "- Aucun texte, commentaire ou balise markdown en dehors du tableau.",
  "cw.prompt_fallback":   "Si tu ne peux pas respecter ces contraintes, renvoie un tableau vide [].",

