  /* ── Limites (LIM) ── */
  "lim.title":             "Limites de fonctions",
  "lim.node_limite_correcte": "Limite correcte ?",
  "lim.mode_aleatoire":    "Aléatoire",
  "lim.mode_fixe":         "Fixe (f(x), point et réponse ci-dessous)",
  "lim.scenario_lbl":      "Type de limite",
  "lim.scenario_plus_inf": "lim x → +∞",
  "lim.scenario_moins_inf":"lim x → −∞",
  "lim.scenario_point_fini":"lim x → a (point fini)",
  "lim.scenario_droite":   "lim x → a⁺ (à droite)",
  "lim.scenario_gauche":   "lim x → a⁻ (à gauche)",
  "lim.point_lbl":         "Point a",
  "lim.expr_lbl":          "Expression f(x)",
  "lim.expr_examples_html":"<code>sin(x)/x</code>, <code>(x^2-1)/(x-1)</code>, <code>exp(x)/x^2</code>, <code>log(x)</code>…",
  "lim.tans_lbl":          "Réponse attendue",
  "lim.tans_examples_html":"Exemples : <code>3</code>, <code>0</code>, <code>inf</code>, <code>-inf</code>, <code>%pi</code>, <code>1/2</code>",
  "lim.fbgen_auto_desc":   "La correction (formule, valeur) est générée automatiquement selon les réglages choisis dans Config.",
  "lim.banniere":          "Limites",
  "lim.calc_limite":       "Calculer la limite :",
  "lim.taper_inf_ou_moins_inf": "Taper <code>inf</code> pour \\(+\\infty\\) ou <code>-inf</code> pour \\(-\\infty\\).",
  "lim.taper_inf":         "Taper <code>inf</code> pour \\(+\\infty\\).",
  "lim.taper_moins_inf":   "Taper <code>-inf</code> pour \\(-\\infty\\).",
  "lim.calc_limite_indetermination": "Calculer (en levant l'indétermination) :",
  "lim.calc_limite_droite": "Calculer la limite à droite :",
  "lim.calc_limite_gauche": "Calculer la limite à gauche :",
  "lim.fb_wrong_fixe":     "<strong>Méthode</strong> : essayer d'abord la substitution directe. Si on obtient une forme indéterminée (0/0, ∞/∞, ∞−∞...), factoriser ou simplifier l'expression avant de reprendre la limite.<br>Réponse attendue : {@{tavar}@}.",
  "lim.fbgen_fixe":        "La limite demandée vaut {@{tavar}@}. Vérifier la substitution directe, et en cas de forme indéterminée, factoriser/simplifier avant de conclure.",
  "lim.fb_wrong_plus_inf": "<strong>Méthode</strong> : pour une limite en \\(+\\infty\\) d'un quotient de polynômes, on compare les degrés du numérateur et du dénominateur (équivalent à mettre en facteur la puissance dominante des deux côtés).<br>Ici, le numérateur \\({@{numvar}@}\\) est de degré {@{degnvar}@} (coefficient dominant {@{lcnvar}@}), et le dénominateur \\({@{denvar}@}\\) est de degré {@{degdvar}@} (coefficient dominant {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; limite 0.<br>• deg(num) = deg(den) &rarr; limite = rapport des coefficients dominants.<br>• deg(num) &gt; deg(den) &rarr; limite infinie.<br>Conclusion : la limite vaut {@{tavar}@}.",
  "lim.fbgen_plus_inf":    "\\(\\displaystyle\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\) : numérateur de degré {@{degnvar}@} (coefficient dominant {@{lcnvar}@}), dénominateur de degré {@{degdvar}@} (coefficient dominant {@{lcdvar}@}).<br>\\(\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_moins_inf":"<strong>Méthode</strong> : pour une limite en \\(-\\infty\\) d'un quotient de polynômes, on compare les degrés du numérateur et du dénominateur.<br>Ici, le numérateur \\({@{numvar}@}\\) est de degré {@{degnvar}@} (coefficient dominant {@{lcnvar}@}), et le dénominateur \\({@{denvar}@}\\) est de degré {@{degdvar}@} (coefficient dominant {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; limite 0.<br>• deg(num) = deg(den) &rarr; limite = rapport des coefficients dominants.<br>• deg(num) &gt; deg(den) &rarr; limite infinie (attention au signe en \\(-\\infty\\)).<br>Conclusion : la limite vaut {@{tavar}@}.",
  "lim.fbgen_moins_inf":   "\\(\\displaystyle\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\) : numérateur de degré {@{degnvar}@} (coefficient dominant {@{lcnvar}@}), dénominateur de degré {@{degdvar}@} (coefficient dominant {@{lcdvar}@}).<br>\\(\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_point_fini":"<strong>Méthode</strong> : numérateur et dénominateur s'annulent tous les deux en \\(x={@{avar}@}\\) (forme indéterminée 0/0). On factorise \\((x-{@{avar}@})\\) au numérateur : \\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\).<br>On simplifie avec le facteur identique au dénominateur : \\(\\frac{(x-{@{avar}@})({@{qvar}@})}{x-{@{avar}@}}={@{qvar}@}\\).<br>Il reste à évaluer en \\(x={@{avar}@}\\) : {@{tavar}@}.",
  "lim.fbgen_point_fini":  "Factoriser \\((x-{@{avar}@})\\) au numérateur (\\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\)), puis simplifier avec le dénominateur : il reste \\({@{qvar}@}\\).<br>Évaluer en \\(x={@{avar}@}\\) donne \\(\\lim={@{tavar}@}\\).",
  "lim.fb_wrong_droite":   "<strong>Méthode</strong> : on pose le changement de variable \\(u=x-{@{avar}@}\\) ; quand \\(x\\to{@{avar}@}^+\\), on a \\(u\\to 0^+\\) (u reste positif).<br>L'expression devient \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\).<br>Quand \\(u\\to 0^+\\), \\(\\sqrt{u}\\to 0^+\\) donc \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fbgen_droite":      "Poser \\(u=x-{@{avar}@}\\to 0^+\\) : l'expression devient \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fb_wrong_gauche":   "<strong>Méthode</strong> : on pose \\(u={@{avar}@}-x\\) ; quand \\(x\\to{@{avar}@}^-\\), on a \\(u\\to 0^+\\), et \\(x-{@{avar}@}=-u\\).<br>L'expression devient \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\).<br>Quand \\(u\\to 0^+\\), \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\), donc l'expression tend vers \\(-\\infty\\).",
