  "log.table_fallback_desc":  "Vérifiez pas à pas l'évaluation de chaque opérateur. Rappel :<br>• L'implication \\(P \\to Q\\) est fausse <u>uniquement</u> si P est vrai et Q est faux.<br>• Le NON s'applique en priorité.",
