  "log.identifier_fallback_desc": "Pour trouver la bonne expression, repérez les lignes où le résultat vaut <strong>1</strong> et déduisez-en le connecteur logique principal :<br>• Si seul (1,1) donne 1 → <em>ET</em><br>• Si seul (0,0) donne 0 → <em>OU</em><br>• Si seul (1,0) donne 0 → <em>IMPLIQUE</em>",
