  /* ── Circuits électriques (CIR) ── */
  "cir.title":              "Circuits électriques (atelier de construction)",
  "cir.teacher_help":       "Construisez ci-dessous le circuit que les élèves devront reproduire à l'identique : cliquez sur un composant à droite pour le placer, cliquez sur deux bornes pour tirer un câble. Cliquez sur un composant du schéma pour le sélectionner (déplacer, tourner, régler sa valeur).",
  "cir.check_values_lbl":   "Exiger aussi les bonnes valeurs des composants (pas seulement le câblage)",
  "cir.text_lbl":           "Énoncé",
  "cir.err_no_model":       "Construisez d'abord un circuit dans l'atelier ci-dessus avant d'enregistrer cette question.",
  "cir.status_components":  "{n} composant(s) placé(s), {m} nœud(s) électrique(s).",
  "cir.status_empty":       "Aucun composant placé — cliquez sur un composant à droite pour commencer.",
  "cir.fbgen_auto_desc":    "La correction est automatique et porte sur trois critères successifs : les composants placés, le câblage (topologie), puis — si activé — les valeurs des composants. Ce champ permet d'ajouter un commentaire pédagogique complémentaire, affiché en plus de la correction.",
  "cir.atelier_title":      "Atelier circuits électriques",
  "cir.atelier_instructions": "Clique sur un composant à droite pour le placer. Clique sur un composant du schéma pour le <strong>sélectionner</strong> : un repère carré gris apparaît, glisse-le pour déplacer le composant. <strong>⟳</strong> pour tourner, l'étiquette (✎) pour changer une valeur. Clique sur deux bornes pour tirer un câble. Un interrupteur déjà sélectionné bascule quand on reclique dessus.",
  "cir.btn_scissors":       "Ciseau",
  "cir.btn_undo":           "Annuler point",
  "cir.btn_reset":          "Vider tout",
  "cir.feedback_placeholder": "Choisis un composant à droite pour commencer.",
  "cir.heading_components": "Composants",
  "cir.heading_value":      "Valeur",
  "cir.valname_placeholder": "Sélectionne un composant",
  "cir.valhint":            "Clique sur un composant du schéma pour régler sa valeur.",
