  "cir.default_instruction_lead": "Consigne :",
  "cir.default_instruction_body1": "Utilisez l'atelier ci-dessous pour construire un circuit identique à celui attendu.",
  "cir.default_instruction_body2_pre": "Une fois terminé, cliquez sur le bouton",
