  "opt.info_lentille_convergente": "✏️ L'élève trace au moins deux des trois rayons particuliers issus de B à l'aide de la barre d'outils (rayon 2 clics, rayon // axe, rayon parallèle 3 clics), puis construit le point B' par intersection des rayons émergents. Le statut réel/virtuel de chaque tronçon est corrigé automatiquement.",
  "opt.info_lentille_divergente": "✏️ Comme pour la lentille convergente, mais l'image est <strong>toujours virtuelle</strong> : les rayons émergents divergent après la lentille et doivent être prolongés en arrière (pointillés) pour construire B'.",
  "opt.info_miroir_plan": "✏️ L'élève trace les deux rayons remarquables issus de B (incidence normale, et rayon arrivant en S), les fait se réfléchir sur le miroir plan, puis construit B' par intersection des rayons réfléchis prolongés. L'image est <strong>toujours virtuelle et de même taille</strong> que l'objet.",
  "opt.info_miroir_concave": "✏️ L'élève trace au moins deux des quatre rayons remarquables issus de B (// axe, par C, par F, vers S), les fait se réfléchir sur le miroir, puis construit B' par intersection des rayons réfléchis. Selon la position de l'objet (SA &lt; f ou SA &gt; f), l'image est virtuelle ou réelle — le statut réel/virtuel attendu de chaque tronçon est corrigé automatiquement.",
  "opt.info_miroir_convexe": "✏️ Comme pour le miroir concave, mais le foyer F et le centre C sont <strong>virtuels</strong> (derrière le miroir) : l'image obtenue est toujours virtuelle, quelle que soit la position de l'objet.",
  "opt.info_lunette_galilee": "✏️ L'élève construit quatre rayons remarquables : deux rayons incidents parallèles (l'un par le centre de l'objectif) qui convergent en B&#8321; dans le plan focal commun, puis deux rayons issus de B&#8321; vers l'oculaire, qui ressortent parallèles (système afocal, image à l'infini). Le point B&#8321; est construit par l'outil « Intersection ».",
  "opt.info_telescope_newton": "✏️ L'élève construit deux rayons incidents parallèles inclinés de θ (l'un touchant le sommet S du miroir primaire, l'autre décalé de h) et leurs rayons réfléchis correspondants (utiliser « Symétrique / axe » pour le rayon réfléchi au sommet), qui convergent au point image B&#8321; dans le plan focal du miroir. Le point B&#8321; est construit par l'outil « Intersection ».",
  "opt.info_microscope": "✏️ L'élève trace au moins deux des trois rayons remarquables issus de B à travers l'objectif L&#8321;, qui convergent en B&#8321; (image réelle intermédiaire, construite par « Intersection »), puis les deux rayons issus de B&#8321; à travers l'oculaire L&#8322;, placé de sorte que B&#8321; soit exactement dans son plan focal objet (réglage pour un œil normal) : le faisceau émergent ressort parallèle (image finale à l'infini).",
